INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','e9ebefcd-c496-45e8-b816-a79f8442ba85',4.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','e9ebefcd-c496-45e8-b816-a79f8442ba85',$$Council Member Love makes properly staffing public-safety departments and pursuing every available funding opportunity to do so among her most urgent priorities, keeping neighborhoods safe — an enforcement-supportive posture.$$,ARRAY['https://gardenavalleynews.org/mayoral-candidate-wanda-love-opens-up/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','d4f18138-a2e0-4110-b925-7387d9d0d16d',4.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','d4f18138-a2e0-4110-b925-7387d9d0d16d',$$Love was the only council member to vote against a 333-unit, five-story development at 169th and Normandie, arguing senior residents' concerns deserved more weight and advocating affordable housing "without destroying single family neighborhoods" — a preservationist residential-zoning stance.$$,ARRAY['https://gardenavalleynews.org/love-wants-to-pave-a-road-for-economic-growth/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','669cac97-66a6-4087-b036-936fbe62efb3',3.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','669cac97-66a6-4087-b036-936fbe62efb3',$$Love supports more affordable housing while opposing large dense developments near single-family areas — a moderate housing position balancing added supply against neighborhood preservation.$$,ARRAY['https://gardenavalleynews.org/love-wants-to-pave-a-road-for-economic-growth/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
INSERT INTO inform.politician_answers (politician_id, topic_id, value) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','eb3d1247-0de1-4b7f-baec-7259861efd53',2.0) ON CONFLICT (politician_id, topic_id) DO UPDATE SET value=EXCLUDED.value;
INSERT INTO inform.politician_context (politician_id, topic_id, reasoning, sources) VALUES ('9544d1f3-4a56-4136-a32f-f57f53de15a6','eb3d1247-0de1-4b7f-baec-7259861efd53',$$Love focuses on economic development, particularly recruiting businesses to generate jobs and revenue for Gardena.$$,ARRAY['https://gardenavalleynews.org/love-wants-to-pave-a-road-for-economic-growth/']::text[]::text[]) ON CONFLICT (politician_id, topic_id) DO UPDATE SET reasoning=EXCLUDED.reasoning, sources=EXCLUDED.sources;
